43	async function generateMessages(preprompt?: string): Promise<Message[]> {
44		const isLinear = faker.datatype.boolean(0.5);
45		const isInterrupted = faker.datatype.boolean(0.05);
46	
47		const messages: Message[] = [];
48	
49		messages.push({
50			id: crypto.randomUUID(),
51			from: "system",
52			content: preprompt ?? "",
53			createdAt: faker.date.recent({ days: 30 }),
54			updatedAt: faker.date.recent({ days: 30 }),
55		});
56	
57		let isUser = true;
58		let lastId = messages[0].id;
59		if (isLinear) {
60			const convLength = faker.number.int({ min: 1, max: 25 }) * 2; // must always be even
61	
62			for (let i = 0; i < convLength; i++) {
63				lastId = addChildren(
64					{
65						messages,
66						rootMessageId: messages[0].id,
67					},
68					{
69						from: isUser ? "user" : "assistant",
70						content:
71							faker.lorem.sentence({
72								min: 10,
73								max: isUser ? 50 : 200,
74							}) +
75							(!isUser && Math.random() < 0.1
76								? "\n```\n" + faker.helpers.arrayElement(samples) + "\n```\n"
77								: ""),
78						createdAt: faker.date.recent({ days: 30 }),
79						updatedAt: faker.date.recent({ days: 30 }),
80						interrupted: !isUser && i === convLength - 1 && isInterrupted,
81					},
82					lastId
83				);
84				isUser = !isUser;
85			}
86		} else {
87			const convLength = faker.number.int({ min: 2, max: 200 });
88	
89			for (let i = 0; i < convLength; i++) {
90				addChildren(
91					{
92						messages,
93						rootMessageId: messages[0].id,
94					},
95					{
96						from: isUser ? "user" : "assistant",
97						content:
98							faker.lorem.sentence({
99								min: 10,
100								max: isUser ? 50 : 200,
101							}) +
102							(!isUser && Math.random() < 0.1
103								? "\n```\n" + faker.helpers.arrayElement(samples) + "\n```\n"
104								: ""),
105						createdAt: faker.date.recent({ days: 30 }),
106						updatedAt: faker.date.recent({ days: 30 }),
107						interrupted: !isUser && i === convLength - 1 && isInterrupted,
108					},
109					faker.helpers.arrayElement([
110						messages[0].id,
111						...messages.filter((m) => m.from === (isUser ? "assistant" : "user")).map((m) => m.id),
112					])
113				);
114	
115				isUser = !isUser;
116			}
117		}
118		return messages;
119	}
