50		const zipfile = new yazl.ZipFile();
51	
52		const promises = [
53			collections.conversations
54				.find({ ...authCondition(locals) })
55				.toArray()
56				.then(async (conversations) => {
57					const formattedConversations = await Promise.all(
58						conversations.map(async (conversation) => {
59							stats.nConversations++;
60							const hashes: string[] = [];
61							conversation.messages.forEach(async (message) => {
62								stats.nMessages++;
63								if (message.files) {
64									message.files.forEach((file) => {
65										hashes.push(file.value);
66									});
67								}
68							});
69							const files = await Promise.all(
70								hashes.map(async (hash) => {
71									try {
72										const fileData = await downloadFile(hash, conversation._id);
73										return fileData;
74									} catch {
75										return null;
76									}
77								})
78							);
79	
80							const filenames: string[] = [];
81							files.forEach((file) => {
82								if (!file) return;
83	
84								const extension = mimeTypes.extension(file.mime) || null;
85								const convId = conversation._id.toString();
86								const fileId = file.name.split("-")[1].slice(0, 8);
87								const fileName = `file-${convId}-${fileId}` + (extension ? `.${extension}` : "");
88								filenames.push(fileName);
89								zipfile.addBuffer(Buffer.from(file.value, "base64"), fileName);
90								stats.nFiles++;
91							});
92	
93							return {
94								...conversation,
95								messages: conversation.messages.map((message) => {
96									return {
97										...message,
98										files: filenames,
99										updates: undefined,
100									};
101								}),
102							};
103						})
104					);
105	
106					zipfile.addBuffer(
107						Buffer.from(JSON.stringify(formattedConversations, null, 2)),
108						"conversations.json"
109					);
110				}),
111			collections.assistants
112				.find({ createdById: locals.user._id })
113				.toArray()
114				.then(async (assistants) => {
115					const formattedAssistants = await Promise.all(
116						assistants.map(async (assistant) => {
117							if (assistant.avatar) {
118								const fileId = collections.bucket.find({
119									filename: assistant._id.toString(),
120								});
121	
122								const content = await fileId.next().then(async (file) => {
123									if (!file?._id) return;
124	
125									const fileStream = collections.bucket.openDownloadStream(file?._id);
126	
127									const fileBuffer = await new Promise<Buffer>((resolve, reject) => {
128										const chunks: Uint8Array[] = [];
129										fileStream.on("data", (chunk) => chunks.push(chunk));
130										fileStream.on("error", reject);
131										fileStream.on("end", () => resolve(Buffer.concat(chunks)));
132									});
133	
134									return fileBuffer;
135								});
136	
137								if (!content) return;
138	
139								zipfile.addBuffer(content, `avatar-${assistant._id.toString()}.jpg`);
140								stats.nAvatars++;
141							}
142	
143							stats.nAssistants++;
144	
145							return {
146								_id: assistant._id.toString(),
147								name: assistant.name,
148								createdById: assistant.createdById.toString(),
149								createdByName: assistant.createdByName,
150								avatar: `avatar-${assistant._id.toString()}.jpg`,
151								modelId: assistant.modelId,
152								preprompt: assistant.preprompt,
153								description: assistant.description,
154								dynamicPrompt: assistant.dynamicPrompt,
155								exampleInputs: assistant.exampleInputs,
156								generateSettings: assistant.generateSettings,
157								createdAt: assistant.createdAt.toISOString(),
158								updatedAt: assistant.updatedAt.toISOString(),
159							};
160						})
161					);
162	
163					zipfile.addBuffer(
164						Buffer.from(JSON.stringify(formattedAssistants, null, 2)),
165						"assistants.json"
166					);
167				}),
168		];
169	
170		Promise.all(promises).then(async () => {
171			logger.info(
172				{
173					userId: locals.user?._id,
174					...stats,
175				},
176				"Exported user data"
177			);
178			zipfile.end();
179			if (locals.user?._id) {
180				await collections.messageEvents.insertOne({
181					userId: locals.user?._id,
182					type: "export",
183					createdAt: new Date(),
184					expiresAt: new Date(Date.now() + 1000 * 60 * 60), // 1 hour
185				});
186			}
187		});
188	
189		// @ts-expect-error - zipfile.outputStream is not typed correctly
190		return new Response(zipfile.outputStream, {
191			headers: {
192				"Content-Type": "application/zip",
193				"Content-Disposition": 'attachment; filename="export.zip"',
194			},
195		});
196	};
