1	/**
2	 * Event Store Persistence (ADR-007)
3	 *
4	 * Provides persistent storage for domain events using SQLite.
5	 * Supports event replay, snapshots, and projections.
6	 *
7	 * Key Features:
8	 * - Append-only event log
9	 * - Event versioning per aggregate
10	 * - Event filtering and queries
11	 * - Snapshot support for performance
12	 * - Event replay for projections
13	 * - Cross-platform SQLite (sql.js fallback)
14	 *
15	 * @module v3/shared/events/event-store
16	 */
17	
18	import { EventEmitter } from 'node:events';
19	import { existsSync, readFileSync, writeFileSync } from 'node:fs';
20	import { createRequire } from 'node:module';
21	import initSqlJs, { Database as SqlJsDatabase } from 'sql.js';
22	import { DomainEvent, AllDomainEvents } from './domain-events.js';
23	
24	// =============================================================================
25	// Event Store Configuration
26	// =============================================================================
27	
28	export interface EventStoreConfig {
29	  /** Path to SQLite database file (:memory: for in-memory) */
30	  databasePath: string;
31	
32	  /** Enable verbose logging */
33	  verbose: boolean;
34	
35	  /** Auto-persist interval in milliseconds (0 = manual only) */
36	  autoPersistInterval: number;
37	
38	  /** Maximum events before snapshot recommendation */
39	  snapshotThreshold: number;
40	
41	  /** Path to sql.js WASM file (optional) */
42	  wasmPath?: string;
43	}
44	
45	const DEFAULT_CONFIG: EventStoreConfig = {
46	  databasePath: ':memory:',
47	  verbose: false,
48	  autoPersistInterval: 5000, // 5 seconds
49	  snapshotThreshold: 100,
50	};
51	
52	// =============================================================================
53	// Event Store Interfaces
54	// =============================================================================
55	
56	export interface EventFilter {
57	  /** Filter by aggregate IDs */
58	  aggregateIds?: string[];
59	
60	  /** Filter by aggregate types */
61	  aggregateTypes?: Array<'agent' | 'task' | 'memory' | 'swarm'>;
62	
63	  /** Filter by event types */
64	  eventTypes?: string[];
65	
66	  /** Filter events after timestamp */
67	  afterTimestamp?: number;
68	
69	  /** Filter events before timestamp */
70	  beforeTimestamp?: number;
71	
72	  /** Filter by minimum version */
73	  fromVersion?: number;
74	
75	  /** Limit number of results */
76	  limit?: number;
77	
78	  /** Offset for pagination */
79	  offset?: number;
80	}
81	
82	export interface EventSnapshot {
83	  /** Aggregate ID */
84	  aggregateId: string;
85	
86	  /** Aggregate type */
87	  aggregateType: 'agent' | 'task' | 'memory' | 'swarm';
88	
89	  /** Version at snapshot */
90	  version: number;
91	
92	  /** Snapshot state */
93	  state: Record<string, unknown>;
94	
95	  /** Timestamp when snapshot was created */
96	  timestamp: number;
97	}
98	
99	export interface EventStoreStats {
100	  totalEvents: number;
101	  eventsByType: Record<string, number>;
102	  eventsByAggregate: Record<string, number>;
103	  oldestEvent: number | null;
104	  newestEvent: number | null;
105	  snapshotCount: number;
106	}
107	
108	// =============================================================================
109	// Event Store Implementation
110	// =============================================================================
111	
112	export class EventStore extends EventEmitter {
113	  private config: EventStoreConfig;
114	  private db: SqlJsDatabase | null = null;
115	  private initialized: boolean = false;
116	  private persistTimer: NodeJS.Timeout | null = null;
117	  private SQL: any = null;
118	
119	  // Version tracking per aggregate
120	  private aggregateVersions: Map<string, number> = new Map();
121	
122	  constructor(config: Partial<EventStoreConfig> = {}) {
123	    super();
124	    this.config = { ...DEFAULT_CONFIG, ...config };
125	  }
126	
127	  /**
128	   * Initialize the event store
129	   */
130	  async initialize(): Promise<void> {
131	    if (this.initialized) return;
132	
133	    // Load sql.js WASM
134	    let wasmLocator: ((file: string) => string) | undefined;
135	    if (this.config.wasmPath) {
136	      wasmLocator = () => this.config.wasmPath!;
137	    } else {
138	      try {
139	        const req = createRequire(import.meta.url);
140	        const sqlJsPath = req.resolve('sql.js/dist/sql-wasm.wasm');
141	        wasmLocator = () => sqlJsPath;
142	      } catch {
143	        wasmLocator = (file: string) => `https://sql.js.org/dist/${file}`;
144	      }
145	    }
146	    this.SQL = await initSqlJs({ locateFile: wasmLocator });
147	
148	    // Load existing database if exists
149	    if (this.config.databasePath !== ':memory:' && existsSync(this.config.databasePath)) {
150	      const buffer = readFileSync(this.config.databasePath);
151	      this.db = new this.SQL.Database(new Uint8Array(buffer));
152	
153	      if (this.config.verbose) {
154	        console.log(`[EventStore] Loaded database from ${this.config.databasePath}`);
155	      }
156	    } else {
157	      this.db = new this.SQL.Database();
158	
159	      if (this.config.verbose) {
160	        console.log('[EventStore] Created new event store database');
161	      }
162	    }
163	
164	    // Create schema
165	    this.createSchema();
166	
167	    // Load aggregate versions
168	    this.loadAggregateVersions();
169	
170	    // Set up auto-persist
171	    if (this.config.autoPersistInterval > 0 && this.config.databasePath !== ':memory:') {
172	      this.persistTimer = setInterval(() => {
173	        this.persist().catch((err) => {
174	          this.emit('error', { operation: 'auto-persist', error: err });
175	        });
176	      }, this.config.autoPersistInterval);
177	    }
178	
179	    this.initialized = true;
180	    this.emit('initialized');
181	  }
182	
183	  /**
184	   * Shutdown the event store
185	   */
186	  async shutdown(): Promise<void> {
187	    if (!this.initialized || !this.db) return;
188	
189	    // Stop auto-persist
190	    if (this.persistTimer) {
191	      clearInterval(this.persistTimer);
192	      this.persistTimer = null;
193	    }
194	
195	    // Final persist
196	    if (this.config.databasePath !== ':memory:') {
197	      await this.persist();
198	    }
199	
200	    this.db.close();
201	    this.db = null;
202	    this.initialized = false;
203	    this.emit('shutdown');
204	  }
205	
206	  /**
207	   * Append a new event to the store
208	   */
209	  async append(event: DomainEvent): Promise<void> {
210	    this.ensureInitialized();
211	
212	    // Get next version for aggregate
213	    const currentVersion = this.aggregateVersions.get(event.aggregateId) || 0;
214	    const nextVersion = currentVersion + 1;
215	
216	    // Set version on event
217	    event.version = nextVersion;
218	
219	    // Insert event
220	    const stmt = `
221	      INSERT INTO events (
222	        id, type, aggregate_id, aggregate_type, version, timestamp,
223	        source, payload, metadata, causation_id, correlation_id
224	      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
225	    `;
226	
227	    this.db!.run(stmt, [
228	      event.id,
229	      event.type,
230	      event.aggregateId,
231	      event.aggregateType,
232	      event.version,
233	      event.timestamp,
234	      event.source,
235	      JSON.stringify(event.payload),
236	      JSON.stringify(event.metadata || {}),
237	      event.causationId || null,
238	      event.correlationId || null,
239	    ]);
240	
241	    // Update version tracker
242	    this.aggregateVersions.set(event.aggregateId, nextVersion);
243	
244	    // Emit event appended notification
245	    this.emit('event:appended', event);
246	
247	    // Check if snapshot needed
248	    if (nextVersion % this.config.snapshotThreshold === 0) {
249	      this.emit('snapshot:recommended', { aggregateId: event.aggregateId, version: nextVersion });
250	    }
251	  }
252	
253	  /**
254	   * Get events for a specific aggregate
255	   */
256	  async getEvents(aggregateId: string, fromVersion?: number): Promise<DomainEvent[]> {
257	    this.ensureInitialized();
258	
259	    let sql = 'SELECT * FROM events WHERE aggregate_id = ?';
260	    const params: any[] = [aggregateId];
261	
262	    if (fromVersion !== undefined) {
263	      sql += ' AND version >= ?';
264	      params.push(fromVersion);
265	    }
266	
267	    sql += ' ORDER BY version ASC';
268	
269	    const stmt = this.db!.prepare(sql);
270	    const events: DomainEvent[] = [];
271	
272	    stmt.bind(params);
273	    while (stmt.step()) {
274	      const row = stmt.getAsObject();
275	      events.push(this.rowToEvent(row));
276	    }
277	
278	    stmt.free();
279	
280	    return events;
281	  }
282	
283	  /**
284	   * Get events by type
285	   */
286	  async getEventsByType(type: string): Promise<DomainEvent[]> {
287	    this.ensureInitialized();
288	
289	    const stmt = this.db!.prepare('SELECT * FROM events WHERE type = ? ORDER BY timestamp ASC');
290	    const events: DomainEvent[] = [];
291	
292	    stmt.bind([type]);
293	    while (stmt.step()) {
294	      const row = stmt.getAsObject();
295	      events.push(this.rowToEvent(row));
296	    }
297	
298	    stmt.free();
299	
300	    return events;
301	  }
302	
303	  /**
304	   * Query events with filters
305	   */
306	  async query(filter: EventFilter): Promise<DomainEvent[]> {
307	    this.ensureInitialized();
308	
309	    let sql = 'SELECT * FROM events WHERE 1=1';
310	    const params: any[] = [];
311	
312	    // Aggregate ID filter
313	    if (filter.aggregateIds && filter.aggregateIds.length > 0) {
314	      sql += ` AND aggregate_id IN (${filter.aggregateIds.map(() => '?').join(',')})`;
315	      params.push(...filter.aggregateIds);
316	    }
317	
318	    // Aggregate type filter
319	    if (filter.aggregateTypes && filter.aggregateTypes.length > 0) {
320	      sql += ` AND aggregate_type IN (${filter.aggregateTypes.map(() => '?').join(',')})`;
321	      params.push(...filter.aggregateTypes);
322	    }
323	
324	    // Event type filter
325	    if (filter.eventTypes && filter.eventTypes.length > 0) {
326	      sql += ` AND type IN (${filter.eventTypes.map(() => '?').join(',')})`;
327	      params.push(...filter.eventTypes);
328	    }
329	
330	    // Timestamp filters
331	    if (filter.afterTimestamp) {
332	      sql += ' AND timestamp > ?';
333	      params.push(filter.afterTimestamp);
334	    }
335	
336	    if (filter.beforeTimestamp) {
337	      sql += ' AND timestamp < ?';
338	      params.push(filter.beforeTimestamp);
339	    }
340	
341	    // Version filter
342	    if (filter.fromVersion) {
343	      sql += ' AND version >= ?';
344	      params.push(filter.fromVersion);
345	    }
346	
347	    // Order by timestamp
348	    sql += ' ORDER BY timestamp ASC';
349	
350	    // Pagination
351	    if (filter.limit) {
352	      sql += ' LIMIT ?';
353	      params.push(filter.limit);
354	    }
355	
356	    if (filter.offset) {
357	      sql += ' OFFSET ?';
358	      params.push(filter.offset);
359	    }
360	
361	    const stmt = this.db!.prepare(sql);
362	    const events: DomainEvent[] = [];
363	
364	    stmt.bind(params);
365	    while (stmt.step()) {
366	      const row = stmt.getAsObject();
367	      events.push(this.rowToEvent(row));
368	    }
369	
370	    stmt.free();
371	
372	    return events;
373	  }
374	
375	  /**
376	   * Replay events from a specific version
377	   */
378	  async *replay(fromVersion: number = 0): AsyncIterable<DomainEvent> {
379	    this.ensureInitialized();
380	
381	    const stmt = this.db!.prepare('SELECT * FROM events WHERE rowid >= ? ORDER BY rowid ASC');
382	    stmt.bind([fromVersion]);
383	
384	    while (stmt.step()) {
385	      const row = stmt.getAsObject();
386	      yield this.rowToEvent(row);
387	    }
388	
389	    stmt.free();
390	  }
391	
392	  /**
393	   * Save a snapshot for an aggregate
394	   */
395	  async saveSnapshot(snapshot: EventSnapshot): Promise<void> {
396	    this.ensureInitialized();
397	
398	    const stmt = `
399	      INSERT OR REPLACE INTO snapshots (
400	        aggregate_id, aggregate_type, version, state, timestamp
401	      ) VALUES (?, ?, ?, ?, ?)
402	    `;
403	
404	    this.db!.run(stmt, [
405	      snapshot.aggregateId,
406	      snapshot.aggregateType,
407	      snapshot.version,
408	      JSON.stringify(snapshot.state),
409	      snapshot.timestamp,
410	    ]);
411	
412	    this.emit('snapshot:saved', snapshot);
413	  }
414	
415	  /**
416	   * Get snapshot for an aggregate
417	   */
418	  async getSnapshot(aggregateId: string): Promise<EventSnapshot | null> {
419	    this.ensureInitialized();
420	
421	    const stmt = this.db!.prepare(
422	      'SELECT * FROM snapshots WHERE aggregate_id = ? ORDER BY version DESC LIMIT 1'
423	    );
424	
425	    const row = stmt.getAsObject([aggregateId]);
426	    stmt.free();
427	
428	    if (!row || Object.keys(row).length === 0) {
429	      return null;
430	    }
431	
432	    return {
433	      aggregateId: row.aggregate_id as string,
434	      aggregateType: row.aggregate_type as any,
435	      version: row.version as number,
436	      state: JSON.parse(row.state as string),
437	      timestamp: row.timestamp as number,
438	    };
439	  }
440	
441	  /**
442	   * Get event store statistics
443	   */
444	  async getStats(): Promise<EventStoreStats> {
445	    this.ensureInitialized();
446	
447	    // Total events
448	    const totalStmt = this.db!.prepare('SELECT COUNT(*) as count FROM events');
449	    const totalRow = totalStmt.getAsObject([]);
450	    totalStmt.free();
451	    const totalEvents = (totalRow.count as number) || 0;
452	
453	    // Events by type
454	    const typeStmt = this.db!.prepare('SELECT type, COUNT(*) as count FROM events GROUP BY type');
455	    const eventsByType: Record<string, number> = {};
456	    while (typeStmt.step()) {
457	      const row = typeStmt.getAsObject();
458	      eventsByType[row.type as string] = (row.count as number) || 0;
459	    }
460	    typeStmt.free();
461	
462	    // Events by aggregate
463	    const aggStmt = this.db!.prepare(
464	      'SELECT aggregate_id, COUNT(*) as count FROM events GROUP BY aggregate_id'
465	    );
466	    const eventsByAggregate: Record<string, number> = {};
467	    while (aggStmt.step()) {
468	      const row = aggStmt.getAsObject();
469	      eventsByAggregate[row.aggregate_id as string] = (row.count as number) || 0;
470	    }
471	    aggStmt.free();
472	
473	    // Timestamp range
474	    const rangeStmt = this.db!.prepare('SELECT MIN(timestamp) as oldest, MAX(timestamp) as newest FROM events');
475	    const rangeRow = rangeStmt.getAsObject([]);
476	    rangeStmt.free();
477	
478	    // Snapshot count
479	    const snapshotStmt = this.db!.prepare('SELECT COUNT(*) as count FROM snapshots');
480	    const snapshotRow = snapshotStmt.getAsObject([]);
481	    snapshotStmt.free();
482	
483	    return {
484	      totalEvents,
485	      eventsByType,
486	      eventsByAggregate,
487	      oldestEvent: (rangeRow.oldest as number) || null,
488	      newestEvent: (rangeRow.newest as number) || null,
489	      snapshotCount: (snapshotRow.count as number) || 0,
490	    };
491	  }
492	
493	  /**
494	   * Persist to disk
495	   */
496	  async persist(): Promise<void> {
497	    if (!this.db || this.config.databasePath === ':memory:') {
498	      return;
499	    }
500	
501	    const data = this.db.export();
502	    const buffer = Buffer.from(data);
503	
504	    writeFileSync(this.config.databasePath, buffer);
505	
506	    if (this.config.verbose) {
507	      console.log(`[EventStore] Persisted ${buffer.length} bytes to ${this.config.databasePath}`);
508	    }
509	
510	    this.emit('persisted', { size: buffer.length, path: this.config.databasePath });
511	  }
512	
513	  // ===== Private Methods =====
514	
515	  private createSchema(): void {
516	    if (!this.db) return;
517	
518	    // Events table
519	    this.db.run(`
520	      CREATE TABLE IF NOT EXISTS events (
521	        id TEXT PRIMARY KEY,
522	        type TEXT NOT NULL,
523	        aggregate_id TEXT NOT NULL,
524	        aggregate_type TEXT NOT NULL,
525	        version INTEGER NOT NULL,
526	        timestamp INTEGER NOT NULL,
527	        source TEXT NOT NULL,
528	        payload TEXT NOT NULL,
529	        metadata TEXT,
530	        causation_id TEXT,
531	        correlation_id TEXT
532	      )
533	    `);
534	
535	    // Indexes for performance
536	    this.db.run('CREATE INDEX IF NOT EXISTS idx_aggregate_id ON events(aggregate_id)');
537	    this.db.run('CREATE INDEX IF NOT EXISTS idx_aggregate_type ON events(aggregate_type)');
538	    this.db.run('CREATE INDEX IF NOT EXISTS idx_event_type ON events(type)');
539	    this.db.run('CREATE INDEX IF NOT EXISTS idx_timestamp ON events(timestamp)');
540	    this.db.run('CREATE INDEX IF NOT EXISTS idx_version ON events(version)');
541	    this.db.run(
542	      'CREATE UNIQUE INDEX IF NOT EXISTS idx_aggregate_version ON events(aggregate_id, version)'
543	    );
544	
545	    // Snapshots table
546	    this.db.run(`
547	      CREATE TABLE IF NOT EXISTS snapshots (
548	        aggregate_id TEXT PRIMARY KEY,
549	        aggregate_type TEXT NOT NULL,
550	        version INTEGER NOT NULL,
551	        state TEXT NOT NULL,
552	        timestamp INTEGER NOT NULL
553	      )
554	    `);
555	
556	    if (this.config.verbose) {
557	      console.log('[EventStore] Schema created successfully');
558	    }
559	  }
560	
561	  private loadAggregateVersions(): void {
562	    if (!this.db) return;
563	
564	    const stmt = this.db.prepare(
565	      'SELECT aggregate_id, MAX(version) as max_version FROM events GROUP BY aggregate_id'
566	    );
567	
568	    while (stmt.step()) {
569	      const row = stmt.getAsObject();
570	      this.aggregateVersions.set(row.aggregate_id as string, (row.max_version as number) || 0);
571	    }
572	
573	    stmt.free();
574	  }
575	
576	  private rowToEvent(row: any): DomainEvent {
577	    return {
